// useState: local state for the text input (it doesn't need to be in Redux)
import { useState } from 'react';
// React Native building blocks
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';

// Typed Redux hooks from step 3
import { useAppDispatch, useAppSelector } from '@/shared/store/hooks';
// Action creators generated by the slice in step 2 (filterChanged added in step 6)
import { filterChanged, todoAdded, todoDeleted, todoToggled } from '../todos.slice';
// Selectors from 5a (selectFilter and selectVisibleTodos added in step 6)
import {
  selectCompletedCount,
  selectFilter,
  selectTodos,
  selectVisibleTodos,
} from '../todos.selectors';
// The row component from 5b
import TodoItem from '../components/todo-item';
// The All / Pending / Completed tabs from step 6
import FilterTabs from '../components/filter-tabs';

// The screen component
const TodosScreen = () => {
  // Full list: still used for the "X of Y completed" total
  const todos = useAppSelector(selectTodos);
  // Only the todos that match the selected tab
  const visibleTodos = useAppSelector(selectVisibleTodos);
  // Which tab is selected
  const filter = useAppSelector(selectFilter);
  // Read how many are completed; re-renders when the number changes
  const completedCount = useAppSelector(selectCompletedCount);
  // Get the dispatch function, used to send actions to the store
  const dispatch = useAppDispatch();

  // Local state: what the user is typing in the "new todo" input
  const [title, setTitle] = useState('');

  // Runs when the user taps "Add" or presses enter on the keyboard
  const handleAdd = () => {
    // Ignore empty or whitespace-only input
    if (!title.trim()) return;
    // Send the "todoAdded" action; prepare() creates the id and status
    dispatch(todoAdded(title));
    // Clear the input for the next todo
    setTitle('');
  };

  // Return the screen's UI
  return (
    // Fill the screen, with padding around the content
    <View style={styles.container}>
      {/* Screen title */}
      <Text style={styles.heading}>My Todos</Text>
      {/* Progress summary, e.g. "1 of 2 completed" */}
      <Text style={styles.summary}>
        {completedCount} of {todos.length} completed
      </Text>

      {/* Row with the input and the Add button */}
      <View style={styles.addRow}>
        {/* Text input for a new todo title */}
        <TextInput
          style={styles.input}                 // outline styling
          value={title}                        // controlled by local state
          onChangeText={setTitle}              // update local state while typing
          placeholder="What needs to be done?" // hint shown when empty
          onSubmitEditing={handleAdd}          // pressing enter/return adds the todo
          returnKeyType="done"                 // label of the keyboard's return key
        />
        {/* Add button; dimmed when the input is empty */}
        <Pressable
          style={[styles.addButton, !title.trim() && styles.addButtonDisabled]}
          onPress={handleAdd}
          disabled={!title.trim()}             // can't tap when there's nothing to add
        >
          {/* Button label */}
          <Text style={styles.addButtonText}>Add</Text>
        </Pressable>
      </View>

      {/* All / Pending / Completed tabs */}
      <FilterTabs
        selected={filter}                                       // highlight the current tab
        onChange={(value) => dispatch(filterChanged(value))}    // tap → update filter in Redux
      />

      {/* The list of todos */}
      <FlatList
        data={visibleTodos}                                  // only the todos for the selected tab
        keyExtractor={(item) => item.id}                     // id is already a unique string
        contentContainerStyle={{ gap: 10, paddingBottom: 20 }} // space between rows and at the end
        ListEmptyComponent={                                 // shown when no todos match the tab
          <Text style={styles.empty}>
            {filter === 'all' ? 'No todos yet. Add one above.' : `No ${filter} todos.`}
          </Text>
        }
        renderItem={({ item }) => (                          // how to draw each todo
          <TodoItem
            todo={item}                                      // the todo for this row
            onToggle={(id) => dispatch(todoToggled(id))}     // tap → flip pending/completed
            onDelete={(id) => dispatch(todoDeleted(id))}     // delete → remove from list
          />
        )}
      />
    </View>
  );
};

// Export so the layout can show it
export default TodosScreen;

// Styles for the screen
const styles = StyleSheet.create({
  // Whole screen
  container: {
    flex: 1,                    // fill the height so the list can scroll
    padding: 16,                // space around everything
    gap: 12,                    // space between title, summary, input row and list
  },
  // "My Todos"
  heading: {
    fontSize: 28,
    fontWeight: '700',
  },
  // "1 of 2 completed"
  summary: {
    color: '#666',
  },
  // Input + button row
  addRow: {
    flexDirection: 'row',       // side by side
    gap: 8,                     // space between them
  },
  // The text input
  input: {
    flex: 1,                    // take all width except the button
    height: 46,
    borderWidth: 1.5,
    borderColor: '#ccc',
    borderRadius: 10,
    paddingHorizontal: 12,
    fontSize: 16,
  },
  // The Add button
  addButton: {
    height: 46,
    paddingHorizontal: 18,
    borderRadius: 10,
    backgroundColor: '#3c87f7',
    justifyContent: 'center',   // center label vertically
  },
  // Add button when disabled
  addButtonDisabled: {
    opacity: 0.4,
  },
  // "Add" label
  addButtonText: {
    color: '#fff',
    fontWeight: '600',
  },
  // Empty list message
  empty: {
    textAlign: 'center',
    color: '#888',
    marginTop: 40,
  },
});